arguments.command:
cd /workspace/results/baseline32 && python3 -I - <<'EOF'
import re
keys = ['critic/score/mean','actor/kl_loss','actor/entropy_loss','actor/pg_loss','actor/pg_clipfrac','actor/ppo_kl','actor/grad_norm','actor/lr','critic/advantages/max','critic/advantages/min','response_length/mean','response_length/max','response_length/clip_ratio','prompt_length/mean','env/number_of_actions/mean','env/finish_ratio','env/number_of_valid_action','env/ratio_of_valid_action','env/number_of_valid_search','state_tokens/coverage','timing_s/step','timing_s/gen','timing_s/update_actor','global_seqlen/mean']
rows=[]
for line in open('train.log', errors='replace'):
    line = re.sub(r'\x1b\[[0-9;]*m','',line)
    m = re.search(r'step:(\d+) - (.*)', line)
    if not m: continue
    step=int(m.group(1)); d={}
    for kv in m.group(2).split(' - '):
        if ':' in kv:
            k,v = kv.rsplit(':',1)
            try: d[k]=float(v)
            except: d[k]=v
    rows.append((step,d))
short = {'critic/score/mean':'score','actor/kl_loss':'kl','actor/entropy_loss':'ent','actor/pg_loss':'pg','actor/pg_clipfrac':'clipf','actor/ppo_kl':'ppokl','actor/grad_norm':'gnorm','actor/lr':'lr','critic/advantages/max':'advmax','critic/advantages/min':'advmin','response_length/mean':'rlen','response_length/max':'rlmax','response_length/clip_ratio':'rclip','prompt_length/mean':'plen','env/number_of_actions/mean':'nact','env/finish_ratio':'finish','env/number_of_valid_action':'nvalid','env/ratio_of_valid_action':'rvalid','env/number_of_valid_search':'nsearch','state_tokens/coverage':'stcov','timing_s/step':'t_step','timing_s/gen':'t_gen','timing_s/update_actor':'t_upd','global_seqlen/mean':'seqlen'}
print('step ' + ' '.join(f'{short[k]:>7}' for k in keys))
for step,d in rows:
    if 'val/em' in d:
        print(f'{step:>4} VAL em={d["val/em"]} f1={d["val/f1"]} fmt={d["val/format"]} searched={d["val/searched"]} n={d["val/count"]}')
    else:
        print(f'{step:>4} ' + ' '.join(f'{d.get(k,float("nan")):>7.3f}' for k in keys))
EOF

