arguments.command:
cd /workspace/results/baseline32/rollouts && python3 -I - <<'EOF'
import json, re, collections
for step in [1,2,16]:
    recs=[json.loads(l) for l in open(f'step_{step}.jsonl')]
    blocks=collections.Counter()
    for r in recs:
        for b in re.findall(r'<information>(.*?)</information>', r['response'], re.DOTALL):
            blocks[b.strip()[:120]]+=1
    print(f"--- step {step} distinct info-block prefixes ---")
    for k,v in blocks.most_common():
        print(f"  x{v}: {k!r}")
    # Records without <information>
    for r in recs:
        if '<information>' not in r['response']:
            print(f"  NO-INFO record: gen={r['generated_response'][:200]!r}")
            break
EOF

